import math
def diagnose(expected,received,queue_pending,wal_cutoff_ms,backfill):
    if type(queue_pending) is not int or queue_pending<0 or type(wal_cutoff_ms) is not int or wal_cutoff_ms<0:raise ValueError("invalid queue or WAL evidence")
    def parse(rows):
        if not isinstance(rows,list):raise ValueError("sample list required")
        out={}
        for row in rows:
            if not isinstance(row,(list,tuple)) or len(row)!=2:raise ValueError("timestamp/value pair required")
            stamp,value=row
            if type(stamp) is not int or stamp<=0 or type(value) not in (int,float) or not math.isfinite(value) or stamp in out:raise ValueError("invalid or duplicate sample")
            out[stamp]=value
        return out
    source=parse(expected);remote=parse(received)
    if not source:raise ValueError("empty source evidence is not completeness proof")
    if any(stamp in remote and remote[stamp]!=value for stamp,value in source.items()):raise ValueError("received values conflict with source evidence")
    if not isinstance(backfill,dict) or set(backfill)!={"complete_verified_copy","supported_import"} or any(type(v) is not bool for v in backfill.values()):raise ValueError("explicit backfill evidence required")
    missing=sorted(set(source)-set(remote))
    beyond=[stamp for stamp in missing if stamp<wal_cutoff_ms]
    retained=[stamp for stamp in missing if stamp>=wal_cutoff_ms]
    return dict(missing_sample_times=missing,beyond_wal_window=beyond,awaiting_or_unverified=retained,
        history_complete=not missing,queue_pending=queue_pending,
        new_sample_observed=any(stamp>max(source) for stamp in remote),
        gap_bounds_ms=[min(beyond),max(beyond)] if beyond else None,
        backfill_authorized=bool(beyond) and all(backfill.values()),fill_values=None)
```

